let dbPromise;
async function db() { if (!mongoUri) throw new Error('MONGODB_URI is not configured.'); if (!dbPromise) { const client = new MongoClient(mongoUri); dbPromise = client.connect().then(async c => { const database=c.db('quickcart'); try { await database.collection('orders').createIndex({storeId:1,clientOrderId:1},{unique:true,partialFilterExpression:{clientOrderId:{$type:'string'}},name:'orders_store_clientOrder_unique'}); } catch(error) { console.error('Unable to ensure order idempotency index:',error?.message||error); } try { await database.collection('orders').createIndex({customerId:1,createdAt:-1},{name:'orders_customer_createdAt'}); } catch(error) { console.error('Unable to ensure customer order index:',error?.message||error); } try { await database.collection('orders').createIndex({customerEmail:1,createdAt:-1},{name:'orders_customer_email_createdAt'}); } catch(error) { console.error('Unable to ensure customer email order index:',error?.message||error); } try { await database.collection('customer_users').createIndex({email:1},{unique:true,name:'customer_users_email_unique'}); } catch(error) { console.error('Unable to ensure customer email uniqueness:',error?.message||error); } try { await database.collection('customers').createIndex({storeId:1,customerEmail:1},{name:'customers_store_email'}); } catch(error) { console.error('Unable to ensure store customer email index:',error?.message||error); } return database; }); } return dbPromise; }
function tokenFor(user) { if (!jwtSecret) throw new Error('JWT_SECRET is not configured.'); return jwt.sign({ sub: user.id, email: user.email, name: user.name }, jwtSecret, { expiresIn: '7d' }); }
function auth(req, res, next) { try { const h=String(req.headers.authorization||''); const token=h.startsWith('Bearer ')?h.slice(7).trim():''; if(!token||!jwtSecret)return res.status(401).json({error:'Authentication required.',code:'AUTH_REQUIRED'}); const payload=jwt.verify(token,jwtSecret); if(!payload?.sub)return res.status(401).json({error:'Invalid session.',code:'INVALID_SESSION'}); req.user=payload; next(); } catch { return res.status(401).json({error:'Invalid or expired session.',code:'INVALID_SESSION'}); } }
const hashToken = token => createHash('sha256').update(token).digest('hex');
function customerTokenFor(customer) { if (!jwtSecret) throw new Error('JWT_SECRET is not configured.'); return jwt.sign({ sub: customer.id, email: customer.email, name: customer.name, role: 'customer' }, jwtSecret, { expiresIn: '30d' }); }
function customerAuth(req, res, next) { try { const h=String(req.headers.authorization||''); const token=h.startsWith('Bearer ')?h.slice(7).trim():''; if(!token||!jwtSecret)return res.status(401).json({error:'Customer authentication required.',code:'CUSTOMER_AUTH_REQUIRED'}); const payload=jwt.verify(token,jwtSecret); if(payload?.role!=='customer'||!payload?.sub)return res.status(401).json({error:'Invalid customer session.',code:'INVALID_CUSTOMER_SESSION'}); req.customer=payload; next(); } catch { return res.status(401).json({error:'Invalid or expired customer session.',code:'INVALID_CUSTOMER_SESSION'}); } }
const createOtp = () => String(randomInt(100000, 1000000));
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const now = () => new Date().toISOString();
const slugify = value => String(value).toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48);
const PLAN_CONFIG={Free:{price:0,storeLimit:3,features:['Branded storefront','Products and orders','WhatsApp checkout','Basic analytics']},Premium:{price:4999,storeLimit:5,features:['Everything in Free','Advanced analytics','Discounts and promotions','Up to 5 storefronts']},Business:{price:9999,storeLimit:null,features:['Everything in Premium','Unlimited storefronts','Business analytics','Priority support']}};
function planFor(user){const raw=PLAN_CONFIG[user?.plan]?user.plan:'Free';const expiresAt=user?.planExpiresAt||null;const paidActive=user?.subscription===true&&!!expiresAt&&new Date(expiresAt)>new Date();return raw==='Free'?'Free':(paidActive?raw:'Free');}
function planStoreLimit(plan){return PLAN_CONFIG[plan]?.storeLimit??3;}

async function getUserStore(database, req) { const stores=database.collection('stores'); const requestedId=String(req.headers['x-store-id']||''); if(requestedId){ const selected=await stores.findOne({id:requestedId,userId:req.user.sub}); if(selected)return selected; } return stores.findOne({userId:req.user.sub},{sort:{createdAt:1}}); }

async function sendVerificationEmail(email,name,otp){
 if(!brevoApiKey) throw new Error('BREVO_API_KEY is not configured.');
 if(!brevoFromEmail) throw new Error('BREVO_FROM_EMAIL is not configured.');
 const response=await fetch('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{accept:'application/json','api-key':brevoApiKey,'content-type':'application/json'},body:JSON.stringify({sender:{name:brevoFromName,email:brevoFromEmail},to:[{email,name}],subject:'Your QuickCart verification code',textContent:`Hi ${name||'there'}, your QuickCart verification code is ${otp}. It expires in 10 minutes.`,htmlContent:`<html><body style="font-family:Arial,sans-serif;background:#f5f8f6;padding:30px"><div style="max-width:520px;margin:auto;background:#fff;padding:32px;border-radius:16px"><h1>Welcome to QuickCart 👋</h1><p>Hi ${name||'there'},</p><p>Use this code to verify your email:</p><div style="font-size:32px;font-weight:700;letter-spacing:8px;background:#eef5f1;padding:18px;text-align:center;border-radius:12px">${otp}</div><p>This code expires in 10 minutes.</p></div></body></html>`})});
 const data=await response.json().catch(()=>({})); if(!response.ok) throw new Error(data.message||'Unable to send verification email.'); return data;
}

app.get('/api/_healthcheck',async(_req,res)=>{try{const database=await db();await database.command({ping:1});const ready=Boolean(jwtSecret&&brevoApiKey&&brevoFromEmail);if(!ready)return res.status(503).json({ok:false,database:'connected',authentication:jwtSecret?'configured':'unavailable',emailProvider:brevoApiKey&&brevoFromEmail?'configured':'unavailable'});res.json({ok:true,database:'connected',authentication:'configured',emailProvider:'configured'});}catch(error){console.error('Health check failed:',error?.message||error);res.status(503).json({ok:false,database:'unavailable',error:'Service dependencies are not ready.'});}});

app.post('/api/customer/auth/signup',async(req,res)=>{try{const database=await db(),customers=database.collection('customer_users');const email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||''),name=String(req.body.name||'').trim();if(!name||name.length>100||!emailPattern.test(email)||password.length<6||password.length>128)return res.status(400).json({error:'Enter a valid name and email, and a password between 6 and 128 characters.',code:'INVALID_CUSTOMER_SIGNUP'});if(await customers.findOne({email}))return res.status(409).json({error:'An account with that email already exists.',code:'CUSTOMER_EMAIL_EXISTS'});const otp=createOtp();const customer={id:randomUUID(),name,email,passwordHash:await bcrypt.hash(password,12),emailVerified:false,emailVerificationOtpHash:hashToken(otp),emailVerificationExpiresAt:new Date(Date.now()+600000),emailVerificationAttempts:0,emailVerificationSentAt:new Date(),createdAt:now()};try{await customers.insertOne(customer);await sendVerificationEmail(email,name,otp);}catch(e){await customers.deleteOne({id:customer.id});throw e;}res.status(201).json({message:'Customer account created. Enter the verification code sent to your email.',email});}catch(error){console.error(error);if(error?.code===11000)return res.status(409).json({error:'An account with that email already exists.',code:'CUSTOMER_EMAIL_EXISTS'});res.status(503).json({error:'Unable to send the verification email. Please try again.',code:'CUSTOMER_EMAIL_DELIVERY_FAILED'});}});
app.post('/api/customer/auth/verify-otp',async(req,res)=>{try{const email=String(req.body.email||'').trim().toLowerCase(),otp=String(req.body.otp||'').trim();if(!emailPattern.test(email)||!/^[0-9]{6}$/.test(otp))return res.status(400).json({error:'Enter a valid email and the 6-digit verification code.',code:'INVALID_CUSTOMER_OTP'});const database=await db(),customers=database.collection('customer_users'),customer=await customers.findOne({email});if(!customer)return res.status(404).json({error:'Customer account not found.',code:'CUSTOMER_NOT_FOUND'});if(Number(customer.emailVerificationAttempts||0)>=5)return res.status(429).json({error:'Too many incorrect attempts. Request a new code.',code:'CUSTOMER_OTP_ATTEMPTS_EXCEEDED'});if(!customer.emailVerificationExpiresAt||new Date(customer.emailVerificationExpiresAt)<=new Date())return res.status(400).json({error:'This code has expired. Request a new code.',code:'CUSTOMER_OTP_EXPIRED'});if(hashToken(otp)!==customer.emailVerificationOtpHash){await customers.updateOne({id:customer.id},{$inc:{emailVerificationAttempts:1}});return res.status(400).json({error:'Incorrect verification code.',code:'INVALID_CUSTOMER_OTP'});}await customers.updateOne({id:customer.id},{$set:{emailVerified:true},$unset:{emailVerificationOtpHash:'',emailVerificationExpiresAt:'',emailVerificationAttempts:'',emailVerificationSentAt:''}});res.json({token:customerTokenFor(customer),customer:{id:customer.id,name:customer.name,email:customer.email}});}catch(error){console.error(error);res.status(500).json({error:'Unable to verify customer email.',code:'CUSTOMER_OTP_VERIFY_FAILED'});}});
app.post('/api/customer/auth/login',async(req,res)=>{try{const database=await db(),customers=database.collection('customer_users'),email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||'');if(!emailPattern.test(email)||!password)return res.status(400).json({error:'Enter your email and password.',code:'INVALID_CUSTOMER_LOGIN'});const customer=await customers.findOne({email});if(!customer||!customer.passwordHash||!await bcrypt.compare(password,customer.passwordHash))return res.status(401).json({error:'Email or password is incorrect.',code:'INVALID_CUSTOMER_CREDENTIALS'});if(customer.emailVerified!==true)return res.status(403).json({error:'Please verify your email before signing in.',code:'CUSTOMER_EMAIL_NOT_VERIFIED'});res.json({customer:{id:customer.id,name:customer.name,email:customer.email},token:customerTokenFor(customer)});}catch(error){console.error(error);res.status(500).json({error:'Unable to sign in.',code:'CUSTOMER_LOGIN_FAILED'});}});
