app.post('/api/auth/signup',async(req,res)=>{try{const database=await db(),users=database.collection('users');const email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||''),name=String(req.body.name||'').trim();if(!name||name.length>100||!emailPattern.test(email)||password.length<6||password.length>128)return res.status(400).json({error:'Enter a valid name and email, and a password between 6 and 128 characters.',code:'INVALID_SIGNUP'});if(await users.findOne({email}))return res.status(409).json({error:'An account with that email already exists.',code:'EMAIL_EXISTS'});const otp=createOtp();const user={id:randomUUID(),name,email,passwordHash:await bcrypt.hash(password,12),emailVerified:false,emailVerificationOtpHash:hashToken(otp),emailVerificationExpiresAt:new Date(Date.now()+600000),emailVerificationAttempts:0,emailVerificationSentAt:new Date(),emailVerificationResends:0,subscription:false,plan:'Free',createdAt:now()};try{await users.insertOne(user);await sendVerificationEmail(email,name,otp);}catch(e){await users.deleteOne({id:user.id});throw e;}res.status(201).json({message:'Account created. Enter the verification code sent to your email.',requiresVerification:true,email});}catch(error){console.error(error);if(error?.code===11000)return res.status(409).json({error:'An account with that email already exists.',code:'EMAIL_EXISTS'});res.status(503).json({error:'Unable to send the verification email. Please try again.',code:'EMAIL_DELIVERY_FAILED'});}});
app.post('/api/auth/verify-otp',async(req,res)=>{try{const email=String(req.body.email||'').trim().toLowerCase(),otp=String(req.body.otp||'').trim();if(!emailPattern.test(email)||!/^[0-9]{6}$/.test(otp))return res.status(400).json({error:'Enter a valid email and the 6-digit verification code.',code:'INVALID_OTP'});const database=await db(),users=database.collection('users'),user=await users.findOne({email});if(!user)return res.status(404).json({error:'Account not found.',code:'ACCOUNT_NOT_FOUND'});if(user.emailVerified)return res.json({message:'Email is already verified.',token:tokenFor(user),user:{id:user.id,name:user.name,email:user.email}});if(Number(user.emailVerificationAttempts||0)>=5)return res.status(429).json({error:'Too many incorrect attempts. Request a new code.',code:'OTP_ATTEMPTS_EXCEEDED'});if(!user.emailVerificationExpiresAt||new Date(user.emailVerificationExpiresAt)<=new Date())return res.status(400).json({error:'This code has expired. Request a new code.',code:'OTP_EXPIRED'});if(hashToken(otp)!==user.emailVerificationOtpHash){const result=await users.updateOne({id:user.id,emailVerified:false,emailVerificationAttempts:{$lt:5}},{$inc:{emailVerificationAttempts:1}});if(!result.matchedCount)return res.status(429).json({error:'Too many incorrect attempts. Request a new code.',code:'OTP_ATTEMPTS_EXCEEDED'});return res.status(400).json({error:'Incorrect verification code.',code:'INVALID_OTP'});}await users.updateOne({id:user.id,emailVerified:false},{$set:{emailVerified:true},$unset:{emailVerificationOtpHash:'',emailVerificationExpiresAt:'',emailVerificationAttempts:'',emailVerificationSentAt:'',emailVerificationResends:''}});res.json({message:'Email verified successfully.',token:tokenFor({...user,emailVerified:true}),user:{id:user.id,name:user.name,email:user.email}});}catch(error){console.error(error);res.status(500).json({error:'Unable to verify email.',code:'OTP_VERIFY_FAILED'});}});
app.post('/api/auth/resend-otp',async(req,res)=>{try{const email=String(req.body.email||'').trim().toLowerCase();if(!emailPattern.test(email))return res.status(400).json({error:'Enter a valid email address.',code:'INVALID_EMAIL'});const database=await db(),users=database.collection('users'),user=await users.findOne({email});if(!user)return res.status(404).json({error:'No account was found with that email.',code:'ACCOUNT_NOT_FOUND'});if(user.emailVerified)return res.status(400).json({error:'That email is already verified. You can sign in.',code:'ALREADY_VERIFIED'});const sentAt=user.emailVerificationSentAt?new Date(user.emailVerificationSentAt).getTime():0;const elapsed=Date.now()-sentAt;if(sentAt&&elapsed<60000)return res.status(429).json({error:`Please wait ${Math.ceil((60000-elapsed)/1000)} seconds before requesting another code.`,code:'OTP_RESEND_COOLDOWN',retryAfterSeconds:Math.ceil((60000-elapsed)/1000)});const resendWindowStart=user.emailVerificationResendWindowStartedAt?new Date(user.emailVerificationResendWindowStartedAt).getTime():0;const resendCount=Number(user.emailVerificationResends||0);if(resendWindowStart&&Date.now()-resendWindowStart<3600000&&resendCount>=5)return res.status(429).json({error:'Too many verification emails requested. Please try again later.',code:'OTP_RESEND_LIMIT'});const otp=createOtp();try{await sendVerificationEmail(user.email,user.name,otp);}catch(e){console.error(e);return res.status(503).json({error:'Unable to send a new verification email. Please try again.',code:'EMAIL_DELIVERY_FAILED'});}const withinWindow=resendWindowStart&&Date.now()-resendWindowStart<3600000;await users.updateOne({id:user.id},{$set:{emailVerificationOtpHash:hashToken(otp),emailVerificationExpiresAt:new Date(Date.now()+600000),emailVerificationAttempts:0,emailVerificationSentAt:new Date(),emailVerificationResendWindowStartedAt:withinWindow?new Date(resendWindowStart):new Date(),emailVerificationResends:withinWindow?resendCount+1:1}});res.json({message:'A new verification code has been sent.',cooldownSeconds:60});}catch(error){console.error(error);res.status(500).json({error:'Unable to resend verification code.',code:'OTP_RESEND_FAILED'});}});
