app.post('/api/store',auth,async(req,res)=>{const database=await db(),stores=database.collection('stores');const user=await database.collection('users').findOne({id:req.user.sub});const plan=planFor(user);const storeCount=await stores.countDocuments({userId:req.user.sub});const limit=planStoreLimit(plan);if(limit!==null&&storeCount>=limit)return res.status(403).json({error:`${plan} accounts can have up to ${limit} stores.`,code:'STORE_LIMIT_REACHED',plan,limit});const name=String(req.body.storeName||'My Store'),slug=slugify(req.body.slug||name)||`store-${req.user.sub.slice(0,8)}`;if(await stores.findOne({slug}))return res.status(409).json({error:'That store URL is already in use.'});const store={id:randomUUID(),userId:req.user.sub,storeName:name,slug,tagline:String(req.body.tagline||'Shop with us'),vendorPhone:String(req.body.vendorPhone||''),deliveryFee:Number(req.body.deliveryFee||0),deliveryEnabled:req.body.deliveryEnabled===true,primaryColor:String(req.body.primaryColor||'#12392d'),logo:'',paymentDetails:'',deliveryZones:[],discounts:[],createdAt:now()};await stores.insertOne(store);res.status(201).json({store});});
app.put('/api/store',auth,async(req,res)=>{const database=await db(),stores=database.collection('stores'),store=await getUserStore(database,req);if(!store)return res.status(404).json({error:'Store not found.'});const allowed=['storeName','slug','tagline','vendorPhone','deliveryFee','deliveryEnabled','primaryColor','logo','paymentDetails','paymentQrUrl','deliveryZones','discounts'],patch={};for(const key of allowed)if(req.body[key]!==undefined)patch[key]=req.body[key];if(patch.slug!==undefined){patch.slug=slugify(patch.slug);if(await stores.findOne({slug:patch.slug,id:{$ne:store.id}}))return res.status(409).json({error:'That store URL is already in use.'});}if(patch.deliveryFee!==undefined)patch.deliveryFee=Number(patch.deliveryFee);if(patch.deliveryEnabled!==undefined)patch.deliveryEnabled=patch.deliveryEnabled===true||patch.deliveryEnabled==='true';await stores.updateOne({id:store.id,userId:req.user.sub},{$set:patch});res.json({store:await stores.findOne({id:store.id})});});
app.delete('/api/store',auth,async(req,res)=>{try{const database=await db(),stores=database.collection('stores'),requestedId=String(req.body?.storeId||req.headers['x-store-id']||'');const store=requestedId?await stores.findOne({id:requestedId,userId:req.user.sub}):await getUserStore(database,req);if(!store)return res.status(404).json({error:'Store not found.'});await Promise.all([database.collection('products').deleteMany({storeId:store.id}),database.collection('orders').deleteMany({storeId:store.id}),database.collection('discounts').deleteMany({storeId:store.id})]);const result=await stores.deleteOne({id:store.id,userId:req.user.sub});if(!result.deletedCount)return res.status(404).json({error:'Store not found.'});res.json({deleted:true,storeId:store.id});}catch(error){console.error(error);res.status(500).json({error:'Unable to delete the store.'});}});app.get('/api/products',auth,async(req,res)=>{const database=await db(),store=await getUserStore(database,req);if(!store)return res.json({products:[]});res.json({products:await database.collection('products').find({storeId:store.id}).sort({createdAt:-1}).toArray()});});
